//! amdgpu.resource's functions: the machine's AMD graphics device, where
//! its register window is and where each of its blocks' registers are,
//! its blocks powered up and down, and its own memory handed out.
//! A resource: no Open or Close, its first function in the first slot.
//! The base comes from OpenResource("amdgpu.resource").
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/amdgpu_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const amdgpu = @import("../resources/amdgpu.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "amdgpu.resource";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const GetGPUInfo = libraries.lvo(0);
    pub const FindGPUBlock = libraries.lvo(1);
    pub const SetGPUPower = libraries.lvo(2);
    pub const AllocGPUMemory = libraries.lvo(3);
    pub const FreeGPUMemory = libraries.lvo(4);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const GetGPUInfo = *const fn (*AMDGPUBase, *amdgpu.GPUInfo) callconv(.c) bool;
    pub const FindGPUBlock = *const fn (*AMDGPUBase, u32, u32, *amdgpu.GPUBlock) callconv(.c) bool;
    pub const SetGPUPower = *const fn (*AMDGPUBase, u32, u32, bool) callconv(.c) bool;
    pub const AllocGPUMemory = *const fn (*AMDGPUBase, u32, u32, *amdgpu.GPUMemory) callconv(.c) bool;
    pub const FreeGPUMemory = *const fn (*AMDGPUBase, *amdgpu.GPUMemory) callconv(.c) void;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const AMDGPUBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *AMDGPUBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// What the device is and where the machine reaches it, into `info`;
    /// false on a machine without one.
    pub fn GetGPUInfo(self: *AMDGPUBase, info: *amdgpu.GPUInfo) bool {
        return libraries.call(self, LVO.GetGPUInfo, Fn.GetGPUInfo, .{info});
    }

    /// The device's block of kind `id` (GPUBLOCK_*), its `instance`th, into
    /// `block`; false where the device has no such block, or there is no
    /// device.
    pub fn FindGPUBlock(self: *AMDGPUBase, id: u32, instance: u32, block: *amdgpu.GPUBlock) bool {
        return libraries.call(self, LVO.FindGPUBlock, Fn.FindGPUBlock, .{ id, instance, block });
    }

    /// The device's `part` (GPUPOWER_*), its `instance`th, powered up - or
    /// down, with `on` false - by its power manager; false where the manager
    /// refused or did not answer, or there is no device.
    pub fn SetGPUPower(self: *AMDGPUBase, part: u32, instance: u32, on: bool) bool {
        return libraries.call(self, LVO.SetGPUPower, Fn.SetGPUPower, .{ part, instance, on });
    }

    /// `bytes` of the device's own memory, starting on a multiple of
    /// `alignment`, into `memory`; false where there is no room, or no
    /// device. Not cleared.
    pub fn AllocGPUMemory(self: *AMDGPUBase, bytes: u32, alignment: u32, memory: *amdgpu.GPUMemory) bool {
        return libraries.call(self, LVO.AllocGPUMemory, Fn.AllocGPUMemory, .{ bytes, alignment, memory });
    }

    /// A piece from AllocGPUMemory given back; `memory` is cleared.
    pub fn FreeGPUMemory(self: *AMDGPUBase, memory: *amdgpu.GPUMemory) void {
        return libraries.call(self, LVO.FreeGPUMemory, Fn.FreeGPUMemory, .{memory});
    }
};
